package com.hbm.conveyor;
import api.hbm.conveyor.*;import net.minecraft.core.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.syncher.*;import net.minecraft.world.*;import net.minecraft.world.damagesource.DamageSource;import net.minecraft.world.entity.*;import net.minecraft.world.entity.item.ItemEntity;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.Blocks;
/** Original EntityMovingItem's real stack, pickup, strike, NBT and1200tick leave-belt item. */
public final class MovingItem extends MovingConveyorObject implements IConveyorItem {
 private static final EntityDataAccessor<ItemStack> STACK=SynchedEntityData.defineId(MovingItem.class,EntityDataSerializers.ITEM_STACK);
 public MovingItem(EntityType<? extends MovingItem> type,Level level){super(type,level);}public MovingItem(Level level){this(ConveyorObjects.ITEM.get(),level);}
 @Override protected void defineSynchedData(SynchedEntityData.Builder builder){builder.define(STACK,new ItemStack(Blocks.STONE));}public void setItemStack(ItemStack stack){entityData.set(STACK,stack,true);}@Override public ItemStack getItemStack(){return entityData.get(STACK);}
 @Override public InteractionResult interact(Player player,InteractionHand hand){if(!level().isClientSide&&!isRemoved()&&player.getInventory().add(getItemStack().copy())){player.inventoryMenu.broadcastChanges();discard();}return InteractionResult.PASS;}
 @Override public boolean skipAttackInteraction(Entity attacker){knockOff();return false;}@Override public boolean hurt(DamageSource source,float amount){knockOff();return true;}private void knockOff(){if(!level().isClientSide&&!isRemoved()){discard();level().addFreshEntity(new ItemEntity(level(),getX(),getY(),getZ(),getItemStack()));}}
 @Override protected void addAdditionalSaveData(CompoundTag tag){if(!getItemStack().isEmpty())tag.put("Item",getItemStack().save(registryAccess()));}@Override protected void readAdditionalSaveData(CompoundTag tag){var stack=ItemStack.parseOptional(registryAccess(),tag.getCompound("Item"));setItemStack(stack);if(stack.isEmpty())discard();}
 @Override public void enterBlock(IEnterableBlock enterable,BlockPos pos,Direction side){if(isRemoved())return;if(enterable.canItemEnter(level(),pos.getX(),pos.getY(),pos.getZ(),side,this)){enterable.onItemEnter(level(),pos.getX(),pos.getY(),pos.getZ(),side,this);discard();}}
 @Override public boolean onLeaveConveyor(){if(isRemoved())return true;discard();var motion=getDeltaMovement();var item=new ItemEntity(level(),getX()+motion.x*2,getY()+motion.y*2,getZ()+motion.z*2,getItemStack());item.lifespan=1200;item.setDeltaMovement(motion.x*2,.1,motion.z*2);item.hurtMarked=true;level().addFreshEntity(item);return true;}
}
